// Only web addresses become links. Anything else, like javascript: or data:,
// turns into undefined, and an <a> with no href is plain text.
export function safeUrl(value: string): string | undefined {
  try {
    const url = new URL(value);
    return url.protocol === "https:" || url.protocol === "http:" ? url.href : undefined;
  } catch {
    return undefined;
  }
}

import DOMPurify from "dompurify";

type ReviewBodyProps = { html: string };

// Review bodies come from a Markdown editor as HTML. Clean them before React
// puts them in the page: DOMPurify keeps the formatting and drops anything
// that could run, like onerror attributes, javascript: links, and scripts.
export function ReviewBody({ html }: ReviewBodyProps) {
  return <div className="review-body" dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(html) }} />;
}

