type Charge = { id: string; status: "succeeded" | "failed" };

export async function chargeCard(userId: string, amountCents: number, cardToken: string): Promise<Charge> {
  const response = await fetch("https://api.payments.example/v1/charges", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${process.env.PAYMENTS_SECRET_KEY}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ amount: amountCents, currency: "usd", source: cardToken, metadata: { userId } }),
  });
  if (!response.ok) throw new Error(`Payment failed with ${response.status}`);
  return (await response.json()) as Charge;
}
